import{_ as d}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as r,D as n,o as t,c as s,I as p,w as h,k as l,a as _,R as u,b as m,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const O=JSON.parse('{"title":"分栏工作区模型","description":"","frontmatter":{"title":"分栏工作区模型","showArticleMetadata":false,"showComment":false},"headers":[],"relativePath":"open-source/01-dsh-mytable/02-分栏工作区模型.md","filePath":"open-source/01-dsh-mytable/02-分栏工作区模型.md","lastUpdated":1789997903000}'),b={name:"open-source/01-dsh-mytable/02-分栏工作区模型.md"},S=l("h1",{id:"分栏工作区模型",tabindex:"-1"},[_("分栏工作区模型 "),l("a",{class:"header-anchor",href:"#分栏工作区模型","aria-label":'Permalink to "分栏工作区模型"'},"​")],-1),y=u('<p>工作台最有代表性的部分是 <code>src/client/split.tsx</code>：它没有把界面写死成某一种布局，而是用数据模型描述行、窗格、标签和聊天区的位置。</p><h2 id="layoutspec" tabindex="-1">LayoutSpec <a class="header-anchor" href="#layoutspec" aria-label="Permalink to &quot;LayoutSpec&quot;">​</a></h2><p>一个布局由 <code>LayoutSpec</code> 描述，包含：</p><ul><li><code>top</code>、<code>main</code> 与可选的 <code>mid</code> 多行窗格；</li><li>可选的整高左栏 <code>left</code>；</li><li>聊天区宽度、顶行高度、左栏宽度等约束；</li><li><code>chatSide</code> 和 <code>chatFullHeight</code>，控制聊天在左、右或整列显示；</li><li>布局标题、图标与唯一 id。</li></ul><p>窗格本身由 <code>SplitPane</code> 描述。每个窗格可以拥有多个 <code>PaneTab</code>，并记录当前激活标签、最小宽度和标题栏折叠状态。</p><h2 id="内容是联合类型" tabindex="-1">内容是联合类型 <a class="header-anchor" href="#内容是联合类型" aria-label="Permalink to &quot;内容是联合类型&quot;">​</a></h2><p><code>SplitContent</code> 把内容分成四类：</p><ul><li><code>iframe</code>：嵌入允许显示的网页；</li><li><code>builtin</code>：浏览器、资源管理器、Git 改动、任务、终端等内置窗格；</li><li><code>file</code>：本地文件预览；</li><li><code>plugin</code>：由其他 DSH 插件注册的自定义窗口。</li></ul><p>这样一来，布局引擎只关心“内容放在哪”，具体怎么渲染则交给不同内容适配器处理。</p><h2 id="状态变更" tabindex="-1">状态变更 <a class="header-anchor" href="#状态变更" aria-label="Permalink to &quot;状态变更&quot;">​</a></h2><p>分栏引擎支持拖动调整尺寸、移动标签、交换窗格、向右拆分窗格、向下增加一行、切换聊天侧和折叠标题栏。每次结构变化都会通过 <code>onSpecMutated</code> 回传给工作台，再按布局 id 持久化。</p><p>宽度和高度会经过 <code>clamp</code> 限制，并使用 <code>ResizeObserver</code> 与回退的 <code>MutationObserver</code> 跟踪宿主页面变化。这个设计很重要：插件不是独立应用，它必须在 DSH 页面重新渲染或切换会话后重新找到锚点，而不能假设 DOM 永远不变。</p><h2 id="值得保留的设计点" tabindex="-1">值得保留的设计点 <a class="header-anchor" href="#值得保留的设计点" aria-label="Permalink to &quot;值得保留的设计点&quot;">​</a></h2><ul><li>布局是数据，不是散落的 DOM 操作；</li><li>窗格与内容解耦，新增内容类型不必重写布局；</li><li>标签有稳定 id，同内容再次打开时可以去重并聚焦；</li><li>终端标签会自动重新编号，关闭中间标签后不会留下编号空洞；</li><li>支持减少动效和不同窗口尺寸下的边界收敛。</li></ul><p>上一篇：<a href="/open-source/01-dsh-mytable/01-整体架构">整体架构</a> · 下一篇：<a href="/open-source/01-dsh-mytable/03-插件扩展与安全边界">插件扩展与安全边界</a></p>',15);function P(e,k,C,q,x,T){const c=d,i=n("ClientOnly");return t(),s("div",null,[S,p(i,null,{default:h(()=>{var a,o;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((o=e.$frontmatter)==null?void 0:o.showArticleMetadata)??!0)?(t(),m(c,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),y])}const V=r(b,[["render",P]]);export{O as __pageData,V as default};
